            for c in range(3, w - p):
                if grid[r][c] and grid[r][c + p]:
                    total += 1
                    matches += grid[r][c] == grid[r][c + p]
        score = matches / total if total else 0
        if score > best_score:
            best_p, best_score = p, score

    # The pattern advances one position both across and down.
    values = [Counter() for _ in range(best_p)]
    for r in range(3, h):
        for c in range(3, w):
            if grid[r][c] != 0:
                values[(r + c) % best_p][grid[r][c]] += 1

